<?php
$category=(int)($_GET['category']??0);$cats=db()->query('SELECT * FROM cafe_categories WHERE status=1 ORDER BY sort_order,id')->fetchAll();$sql='SELECT i.*,c.name category_name FROM cafe_items i JOIN cafe_categories c ON c.id=i.category_id WHERE i.status=1';$args=[];if($category){$sql.=' AND i.category_id=?';$args[]=$category;}$sql.=' ORDER BY c.sort_order,i.sort_order,i.id';$st=db()->prepare($sql);$st->execute($args);$items=$st->fetchAll();page_header('کافه Majed', 'cafe');
?>
<section class="cafe-hero"><img src="<?=url('assets/images/cafe-hero.jpg')?>" alt="Majed Cafe"><div class="cafe-hero-copy"><p class="kicker">MAJED CAFE / MENU</p><h1>Slow days.<br><em>Good taste.</em></h1><p>منوی کامل کافه؛ از قهوه و نوشیدنی گرم تا صبحانه، فست‌فود، شیک و بستنی.</p></div></section>
<section class="cafe-wrap"><div class="shell"><div class="heading"><div><p>ALL DAY MENU</p><h2>منوی کافه</h2></div><a href="<?=url('admin/cafe')?>">مدیریت منو ↗</a></div><div class="cafe-categories"><a class="<?=$category?'':'active'?>" href="<?=url('cafe')?>">همه</a><?php foreach($cats as $c):?><a class="<?=$category===$c['id']?'active':''?>" href="<?=url('cafe?category='.$c['id'])?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="cafe-menu"><?php foreach($items as $i):?><article class="cafe-item"><?php if($i['image']):?><img src="<?=url('assets/images/'.$i['image'])?>" alt="<?=e($i['name'])?>"><?php endif;?><small style="color:var(--gold)"><?=e($i['category_name'])?></small><h3><?=e($i['name'])?></h3><p><?=e($i['description'])?></p><div class="cafe-price"><span><?=money($i['price'])?></span><span style="color:var(--muted);font-size:.62rem"><?=e($i['category_name'])?></span></div></article><?php endforeach;?></div></div></section>
<?php page_footer(); ?>
